// Interpreta a interação da SDR no grupo: comando de TEXTO ou de ÁUDIO transcrito.
// Aceita: aprovar / reprovar [texto correto] / parar, e também sinônimos falados
// ("sim", "não", "pode mandar", "para a IA", ...), porque quem aprova costuma
// responder por áudio no celular.
const trg = $('Recebe msg do grupo').first().json;
const b   = trg.body ?? trg ?? {};
const src = $json || {};

const transc = String(src.transcricao ?? '').trim();
const veioDeAudio = transc !== '';
const raw = veioDeAudio ? transc : ((b.text && b.text.message) ? b.text.message : (b.body || ''));
const txt = String(raw).trim();

// tira acento preservando o tamanho da string (para cortar o comando do resto pelo índice)
const MAP = {'á':'a','à':'a','â':'a','ã':'a','ä':'a','é':'e','è':'e','ê':'e','ë':'e','í':'i','ì':'i','î':'i','ï':'i',
             'ó':'o','ò':'o','ô':'o','õ':'o','ö':'o','ú':'u','ù':'u','û':'u','ü':'u','ç':'c','ñ':'n'};
const low = txt.toLowerCase().split('').map(c => MAP[c] || c).join('');

const palavras = low.split(/\s+/).filter(Boolean).length;
const curto = palavras <= 4;   // sinônimo só vale em mensagem curta OU seguido de pontuação

const REGRAS = [
  // comandos explícitos: valem sempre
  { acao: 'aprovar',  re: /^(aprovar|aprovado|aprova)([:\-–—,.!]+)?\s*/,    estrito: true  },
  { acao: 'reprovar', re: /^(reprovar|reprovado|reprova)([:\-–—,.!]+)?\s*/, estrito: true  },
  { acao: 'parar',    re: /^(parar|pausar|ia parar|parar a ia|para a ia|pausa a ia|pausar a ia)([:\-–—,.!]+)?\s*/, estrito: true },
  // sinônimos falados: só valem se a mensagem for curta ou tiver pontuação depois
  { acao: 'aprovar',  re: /^(sim|isso|ok|okay|pode enviar|pode mandar|pode|manda|mandar|envia|enviar|perfeito|certo|positivo|beleza|blz)([:\-–—,.!]+)?\s*/, estrito: false },
  { acao: 'reprovar', re: /^(nao|negativo|errado|refazer|corrigir|corrige)([:\-–—,.!]+)?\s*/, estrito: false },
  { acao: 'parar',    re: /^(para|pare|pausa|assumo|eu assumo|deixa comigo)([:\-–—,.!]+)?\s*/, estrito: false },
];

let acao = '', resto = '';
for (const r of REGRAS) {
  const m = low.match(r.re);
  if (!m) continue;
  const temPontuacao = !!(m[2] && m[2].length);
  if (r.estrito || curto || temPontuacao) {
    acao = r.acao;
    resto = txt.slice(m[0].length).trim();
    break;
  }
}
resto = resto.replace(/^[:\-–—,.!?]+\s*/, '');
if (acao === 'parar') resto = '';

const quotedId = b.quotedId || '';
// texto = o que deve ir ao lead: o resto (quando veio junto do comando) ou a mensagem toda
const texto = acao ? resto : txt;

return [{ json: { acao, quotedId, texto, resto, veioDeAudio } }];

