// Extrai o trecho de conhecimento gerado pelo LLM e prepara o documento.
const j = $input.first().json;

let node = j.output?.[0]?.content?.[0]?.text
        ?? j.message?.content
        ?? j.choices?.[0]?.message?.content
        ?? j.content ?? j.text ?? j;

let parsed;
if (node && typeof node === 'object') {
  parsed = node;
} else {
  const s = String(node ?? '');
  try { parsed = JSON.parse(s); }
  catch (e) { const m = s.match(/\{[\s\S]*\}/); parsed = m ? JSON.parse(m[0]) : {}; }
}

const conhecimento = String(parsed.conhecimento || '').trim();

// LLM decidiu que não há conhecimento reaproveitável → não grava nada.
if (!conhecimento) return [];

const par = $('KB: monta par (lead x correção)').first().json;

return [{ json: {
  conteudo: conhecimento,
  deal_id: par.deal_id || '',
  telefone: par.telefone || '',
  por_audio: !!$('Interpreta ação').first().json.veioDeAudio,
  mensagem_lead: par.pergunta_lead || ''
} }];

